import { Component, signal } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { ToastComponent } from './shared/toast/toast';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, ToastComponent],
  templateUrl: './app.html',
  styleUrl: './app.scss'
})
export class App {
  protected readonly title = signal('balconazo-frontend');
}

import { Component } from '@angular/core';
import { ToastComponent } from './shared/toast/toast';
import { AppShellComponent } from './shared/components/app-shell/app-shell';

@Component({
  selector: 'app-root',
  imports: [AppShellComponent, ToastComponent],
  templateUrl: './app.html',
  styleUrl: './app.scss'
})
export class App {
  title = 'Balconazo';
}

/**
 * AppShell Styles
 */

.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.app-main {
  flex: 1;
  padding-top: 0; /* Navbar is sticky, no need for padding */
}

/* Footer */
.app-footer {
  background: var(--gray-900);
  color: var(--gray-300);
  padding: var(--space-20) 0 var(--space-8);
  margin-top: var(--space-20);
}

.footer-container {
  max-width: var(--container-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-column {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.footer-title {
  font-size: var(--text-2xl);
  font-weight: var(--font-extrabold);
  background: linear-gradient(135deg, var(--primary-500), var(--primary-300));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin: 0;
}

.footer-text {
  font-size: var(--text-sm);
  line-height: var(--leading-relaxed);
  color: var(--gray-400);
  margin: 0;
}

.footer-heading {
  font-size: var(--text-sm);
  font-weight: var(--font-bold);
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  margin: 0;
}

.footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);

  a {
    color: var(--gray-400);
    text-decoration: none;
    font-size: var(--text-sm);
    transition: color var(--transition-fast);

    &:hover {
      color: var(--white);
    }
  }
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-8);
  border-top: 1px solid var(--gray-800);
}

.footer-copyright {
  font-size: var(--text-sm);
  color: var(--gray-500);
  margin: 0;
}

.footer-social {
  display: flex;
  gap: var(--space-4);
}

/* Responsive */
@media (max-width: 1023px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 767px) {
  .app-footer {
    padding: var(--space-12) 0 var(--space-6);
    margin-top: var(--space-12);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }
}

import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { NavbarComponent } from '../navbar/navbar';

/**
 * AppShell Component
 * Layout wrapper con navbar + router-outlet + footer
 */
@Component({
  selector: 'app-shell',
  standalone: true,
  imports: [CommonModule, RouterModule, NavbarComponent],
  templateUrl: './app-shell.html',
  styleUrl: './app-shell.scss'
})
export class AppShellComponent {
  currentYear = new Date().getFullYear();
}

/**
 * Navbar Styles
 * Professional sticky navbar with dropdown menu
 */

.navbar {
  position: sticky;
  top: 0;
  height: var(--navbar-height);
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-200);
  z-index: var(--z-sticky);
  transition: all var(--transition-base);
}

.navbar-container {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
}

.navbar-logo {
  font-size: var(--text-2xl);
  font-weight: var(--font-extrabold);
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: var(--tracking-tight);
  text-decoration: none;
  transition: transform var(--transition-fast);

  &:hover {
    transform: scale(1.05);
  }
}

.navbar-menu {
  display: flex;
  gap: var(--space-8);
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
  justify-content: center;
}

.navbar-link {
  color: var(--gray-700);
  font-weight: var(--font-medium);
  font-size: var(--text-base);
  text-decoration: none;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-base);
  transition: all var(--transition-fast);
  position: relative;

  &:hover {
    color: var(--primary-600);
    background: var(--gray-50);
  }

  &.active {
    color: var(--primary-600);
    font-weight: var(--font-semibold);
  }
}

.navbar-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

/* User Menu */
.user-menu-wrapper {
  position: relative;
}

.user-menu-trigger {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2);
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all var(--transition-fast);

  &:hover, &.active {
    border-color: var(--gray-400);
    box-shadow: var(--shadow-sm);
  }

  svg {
    color: var(--gray-600);
    transition: transform var(--transition-fast);
  }

  &.active svg {
    transform: rotate(180deg);
  }
}

.user-avatar {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-full);
  background: var(--primary-600);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: var(--font-bold);
  font-size: var(--text-sm);
}

/* User Dropdown */
.user-dropdown {
  position: absolute;
  top: calc(100% + var(--space-2));
  right: 0;
  min-width: 280px;
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-2xl);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  z-index: var(--z-dropdown);
}

.user-dropdown-header {
  padding: var(--space-5);
  display: flex;
  align-items: center;
  gap: var(--space-3);
  background: var(--gray-50);
}

.user-avatar-large {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--primary-600);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: var(--font-bold);
  font-size: var(--text-lg);
  flex-shrink: 0;
}

.user-info {
  flex: 1;
  min-width: 0;
}

.user-email {
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--gray-900);
  margin: 0 0 var(--space-1);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.user-role-badge {
  display: inline-block;
  padding: var(--space-1) var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--font-semibold);
  border-radius: var(--radius-base);
}

.dropdown-divider {
  height: 1px;
  background: var(--gray-200);
  margin: var(--space-2) 0;
}

.user-dropdown-menu {
  list-style: none;
  margin: 0;
  padding: var(--space-2);
}

.dropdown-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--gray-700);
  text-decoration: none;
  border-radius: var(--radius-base);
  cursor: pointer;
  transition: all var(--transition-fast);
  width: 100%;
  background: none;
  border: none;
  text-align: left;

  svg {
    color: var(--gray-500);
    flex-shrink: 0;
  }

  &:hover {
    background: var(--gray-100);
    color: var(--gray-900);
  }

  &--danger {
    color: var(--error);

    svg {
      color: var(--error);
    }

    &:hover {
      background: var(--error-light);
    }
  }
}

/* Mobile Menu */
.mobile-menu-btn {
  svg {
    display: block;
  }
}

.mobile-backdrop {
  position: fixed;
  top: var(--navbar-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  z-index: calc(var(--z-sticky) - 2);
}

.mobile-menu {
  position: fixed;
  top: var(--navbar-height);
  right: 0;
  bottom: 0;
  width: 80%;
  max-width: 320px;
  background: var(--white);
  box-shadow: var(--shadow-2xl);
  overflow-y: auto;
  z-index: calc(var(--z-sticky) - 1);
  padding: var(--space-6) 0;
}

.mobile-menu-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.mobile-menu-item {
  display: block;
  padding: var(--space-4) var(--space-6);
  font-size: var(--text-base);
  font-weight: var(--font-medium);
  color: var(--gray-700);
  text-decoration: none;
  transition: all var(--transition-fast);
  background: none;
  border: none;
  width: 100%;
  text-align: left;

  &:hover, &:active {
    background: var(--gray-100);
    color: var(--gray-900);
  }

  &--primary {
    color: var(--primary-600);
    font-weight: var(--font-semibold);
  }

  &--danger {
    color: var(--error);
  }
}

.mobile-menu-divider {
  height: 1px;
  background: var(--gray-200);
  margin: var(--space-4) var(--space-6);
}

/* Responsive */
@media (max-width: 767px) {
  .navbar {
    height: 64px;
  }

  .navbar-logo {
    font-size: var(--text-xl);
  }

  .navbar-actions {
    gap: var(--space-2);
  }

  .user-avatar {
    width: 36px;
    height: 36px;
  }
}

/* Focus states */
.navbar-link:focus-visible,
.dropdown-item:focus-visible,
.user-menu-trigger:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';
import { User } from '../../../core/models/auth.model';

/**
 * Navbar Component
 * Barra de navegación profesional con menú por rol
 * 
 * Features:
 * - Sticky navbar con backdrop blur
 * - Logo con gradient
 * - Menú dinámico por rol (HOST/GUEST/No auth)
 * - User dropdown menu
 * - Mobile hamburger menu
 * - Buscador compacto (opcional)
 * - CTA "Publica tu espacio" (solo HOST)
 */
@Component({
  selector: 'app-navbar',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './navbar.html',
  styleUrl: './navbar.scss'
})
export class NavbarComponent implements OnInit {
  private authService = inject(AuthService);
  private router = inject(Router);

  isAuthenticated = false;
  currentUser: User | null = null;
  userRole: string | null = null;
  showMobileMenu = false;
  showUserMenu = false;

  ngOnInit(): void {
    // Suscribirse al estado de autenticación
    this.authService.currentUser$.subscribe(user => {
      this.currentUser = user;
      this.isAuthenticated = this.authService.isAuthenticated();
      this.userRole = this.authService.getUserRole();
    });

    // Cargar usuario inicial si está autenticado
    if (this.authService.isAuthenticated()) {
      const userId = this.authService.getUserId();
      if (userId) {
        this.authService.getProfile().subscribe();
      }
    }
  }

  /**
   * Toggle mobile menu
   */
  toggleMobileMenu(): void {
    this.showMobileMenu = !this.showMobileMenu;
    // Prevenir scroll cuando el menú está abierto
    if (this.showMobileMenu) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
  }

  /**
   * Toggle user dropdown menu
   */
  toggleUserMenu(): void {
    this.showUserMenu = !this.showUserMenu;
  }

  /**
   * Cierra el menú de usuario
   */
  closeUserMenu(): void {
    this.showUserMenu = false;
  }

  /**
   * Cierra el menú móvil
   */
  closeMobileMenu(): void {
    this.showMobileMenu = false;
    document.body.style.overflow = '';
  }

  /**
   * Navega a una ruta y cierra menús
   */
  navigateTo(route: string): void {
    this.router.navigate([route]);
    this.closeMobileMenu();
    this.closeUserMenu();
  }

  /**
   * Logout
   */
  logout(): void {
    this.authService.logout();
    this.closeUserMenu();
    this.closeMobileMenu();
    this.router.navigate(['/']);
  }

  /**
   * Verifica si es HOST
   */
  get isHost(): boolean {
    return this.userRole === 'HOST';
  }

  /**
   * Verifica si es GUEST
   */
  get isGuest(): boolean {
    return this.userRole === 'GUEST';
  }

  /**
   * Obtiene las iniciales del usuario para el avatar
   */
  get userInitials(): string {
    if (!this.currentUser?.email) {
      return 'U';
    }
    return this.currentUser.email.charAt(0).toUpperCase();
  }
}
